"""Mode live coding : questions d'entretien à voix haute, chacune liée à une task vérifiée du site.

Chaque question : la consigne courte telle qu'un intervieweur la dit (anglais), les questions de
clarification qu'un bon candidat pose (avec la réponse de l'intervieweur), puis les relances après le code
(avec les points clés d'une bonne réponse, en français).
"""

PHASES = [
    {"id": "clarify", "title": "Clarifier", "min": 4, "say": "Reformule la consigne avec tes mots, puis pose tes questions : entrées, cas vides, doublons, ordre, taille des données."},
    {"id": "plan", "title": "Plan à voix haute", "min": 4, "say": "UMPIRE : donne un exemple à la main, nomme le pattern, annonce ton plan et sa complexité AVANT de coder."},
    {"id": "code", "title": "Coder en parlant", "min": 20, "say": "Code dans l'éditeur en expliquant chaque bloc. Si tu bloques, dis ce que tu essaies, ne reste jamais silencieux plus de 30 secondes."},
    {"id": "test", "title": "Tester à voix haute", "min": 4, "say": "Déroule ton code sur l'exemple, puis sur un cas limite. Lance les tests seulement après."},
    {"id": "follow", "title": "Relances", "min": 8, "say": "Réponds à chaque relance en 1 à 2 minutes : idée, complexité, limite, puis comment tu le testerais."},
]

